/**
 * Paksa IT Solutions — Icon Library
 * Phosphor-style duotone SVG icons. aria-hidden on all decorative icons.
 * Use paksa_icon( $name, $size ) anywhere in templates.
 * @package paksa-it-solutions
 */

if ( ! defined( 'ABSPATH' ) ) { exit; }

function paksa_icon( $name, $size = 24 ) {
    static $icons = null;
    if ( $icons === null ) { $icons = paksa_icon_library(); }
    $svg = isset( $icons[ $name ] ) ? $icons[ $name ] : $icons['gear'];
    if ( $size !== 24 ) {
        $svg = preg_replace( '/width="24" height="24"/', 'width="' . $size . '" height="' . $size . '"', $svg );
    }
    return $svg;
}

