function paksa_get_capability_icon( $name ) { return paksa_icon( $name ); }
function paksa_get_intelligence_icon( $name ) { return paksa_icon( $name, 20 ); }
function paksa_get_why_icon( $name ) { return paksa_icon( $name, 22 ); }
function paksa_get_industry_icon( $name ) { return paksa_icon( $name, 20 ); }
function paksa_get_outcome_icon( $name ) { return paksa_icon( $name, 22 ); }
